INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(11337, 'koKR', 'Wezwanie do boju: Oko Cyklonu', 'Walka z Hordą nie zna granic, $N. Nawet w Rubieży spory terytorialne i dawne nienawiści wystarczą, by przechylić szalę na stronę wojny.$B$BUdaj się do Oka Cyklonu i dopilnuj, by Przymierze zwyciężyło w Rubieży tak samo, jak zwyciężyło w Azeroth.', 'Wygraj bitwę w Oku Cyklonu i wróć do generała brygady Przymierza w dowolnej stolicy Przymierza, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo w Oku Cyklonu', '', '', '', '', '', 0),
(11341, 'koKR', 'Wezwanie do boju: Oko Cyklonu', 'Będziemy walczyć z wrogiem i miażdżyć go wszędzie, gdzie go znajdziemy. Azeroth, Rubież – miejsce nie ma znaczenia.$B$BNie możemy pozwolić, by Przymierze zdobyło przewagę w Oku Cyklonu. Uderz na nich dziś... jutro może być za późno!', 'Wygraj bitwę w Oku Cyklonu i wróć do zwiastuna wojny Hordy w dowolnej stolicy Hordy, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo w Oku Cyklonu', '', '', '', '', '', 0),
