INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(11337, 'koKR', 'Jesteśmy o krok bliżej całkowitego zwycięstwa nad Hordą. Nie możemy pozwolić, by wróg zdobył przyczółek w tym ani w żadnym innym świecie.', 0),
(11341, 'koKR', 'Przynosisz nam wszystkim chlubę, $N. Musimy pokazać wrogowi, że będziemy z nim walczyć wszędzie, gdzie go znajdziemy.', 0),
(14179, 'koKR', 'Jesteśmy o krok bliżej całkowitego zwycięstwa nad Hordą. Nie możemy pozwolić, by wróg zdobył przyczółek w tym ani w żadnym innym świecie.', 0),
(14182, 'koKR', 'Przynosisz nam wszystkim chlubę, $N. Musimy pokazać wrogowi, że będziemy z nim walczyć wszędzie, gdzie go znajdziemy.', 0);
